import random,exact,numpy as np
for it in range(10000):
 K=random.randint(1,8);meas=[]
 for _ in range(random.randint(0,20)):
  a=random.randrange(K);b=random.randrange(K);L=random.randint(-20,20);U=random.randint(-20,20)
  if L>U:L,U=U,L
  meas.append([a,b,L,U])
 prof={'groups':K,'jitter_ps':[0]*K,'measurements':meas}
 # independent-ish Floyd check
 INF=10**9;d=np.full((K,K),INF,dtype=np.int64);np.fill_diagonal(d,0)
 for a,b,L,U in meas:
  d[a,b]=min(d[a,b],U);d[b,a]=min(d[b,a],-L)
 for k in range(K):
  for i in range(K):
   for j in range(K):
    if d[i,k]+d[k,j]<d[i,j]:d[i,j]=d[i,k]+d[k,j]
 infeas=any(d[i,i]<0 for i in range(K))
 cal=exact.solve_calibration(prof)
 if cal.feasible == infeas:
  print('FEAS MISMATCH',it,K,meas,infeas,cal.artifact,d.tolist());break
 if not cal.feasible and not exact._valid_negative_cycle(prof,cal.artifact['cycle']):
  print('CYC BAD',it,K,meas,cal.artifact);break
else:print('10000 calibration fuzz okay')
PY
